#!/bin/bash

# ===================================
# Script de démarrage RMI - Mini-ERP
# ===================================
# 
# Ce script facilite le démarrage du projet avec Java RMI activé
# 
# Usage: ./start-with-rmi.sh [options]
#
# Options:
#   docker      Lancer avec Docker Compose (par défaut)
#   local       Lancer localement sur la machine (nécessite Maven et Java)
#   stop        Arrêter les services (Docker Compose uniquement)
#   clean       Nettoyer et reconstruire
#   logs        Afficher les logs en temps réel
#

set -e

SCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\ncd \"$SCRIPT_DIR\"\n\necho \"═════════════════════════════════════════════════════════════════════\"\necho \"             Mini-ERP - Java RMI Startup Script\"\necho \"═════════════════════════════════════════════════════════════════════\"\necho \"\"\n\n# Fonction pour afficher l'aide\nshow_help() {\n    echo \"Usage: ./start-with-rmi.sh [docker|local|stop|clean|logs]\"\n    echo \"\"\n    echo \"Options:\"\n    echo \"  docker   - Lancer avec Docker Compose (par défaut)\"\n    echo \"  local    - Lancer localement\"\n    echo \"  stop     - Arrêter les services\"\n    echo \"  clean    - Nettoyer et reconstruire\"\n    echo \"  logs     - Afficher les logs\"\n    echo \"\"\n}\n\n# Fonction pour lancer avec Docker Compose\nstart_docker() {\n    echo \"🐳 Lancement avec Docker Compose...\"\n    echo \"\"\n    \n    # Construire d'abord le module RMI commun\n    echo \"📦 Construction du module RMI commun...\"\n    if [ -d \"rmi-common\" ]; then\n        cd rmi-common\n        mvn clean install -q\n        cd ..\n        echo \"✅ Module RMI commun construit avec succès\"\n    else\n        echo \"⚠️  Module rmi-common non trouvé\"\n    fi\n    \n    echo \"\"\n    echo \"🚀 Lancement des services...\"\n    docker-compose up -d\n    \n    echo \"\"\n    echo \"⏳ Attendre que les services démarrent (30 secondes)...\"\n    sleep 30\n    \n    echo \"\"\n    echo \"═════════════════════════════════════════════════════════════════════\"\n    echo \"✅ Services démarrés avec succès!\"\n    echo \"═════════════════════════════════════════════════════════════════════\"\n    echo \"\"\n    echo \"📍 Points d'accès:\"\n    echo \"   • Frontend         : http://localhost:3000\"\n    echo \"   • API Gateway      : http://localhost:8080\"\n    echo \"   • Stock Service    : http://localhost:8081\"\n    echo \"   • Ventes Service   : http://localhost:8082\"\n    echo \"   • Finance Service  : http://localhost:8083\"\n    echo \"\"\n    echo \"📡 Services RMI:\"\n    echo \"   • Stock Service RMI    : rmi://localhost:1099/StockService\"\n    echo \"   • Ventes Service RMI   : rmi://localhost:1100/VentesService\"\n    echo \"   • Finance Service RMI  : rmi://localhost:1101/FinanceService\"\n    echo \"\"\n    echo \"📊 RabbitMQ:\"\n    echo \"   • Management UI : http://localhost:15672 (guest/guest)\"\n    echo \"\"\n    echo \"📖 Documentation:\"\n    echo \"   • Guide RMI             : ./RMI_GUIDE.md\"\n    echo \"   • Résumé modifications  : ./RMI_MODIFICATIONS_SUMMARY.md\"\n    echo \"   • Rapport architecture  : ./RAPPORT_ARCHITECTURE.md\"\n    echo \"\"\n    echo \"💡 Commandes utiles:\"\n    echo \"   • Voir les logs      : docker-compose logs -f\"\n    echo \"   • Arrêter services   : docker-compose down\"\n    echo \"   • Nettoyer volumes   : docker-compose down -v\"\n    echo \"\"\n}\n\n# Fonction pour lancer localement\nstart_local() {\n    echo \"💻 Lancement en local...\"\n    echo \"\"\n    \n    echo \"📦 Construction du module RMI commun...\"\n    if [ -d \"rmi-common\" ]; then\n        cd rmi-common\n        mvn clean install -q\n        cd ..\n        echo \"✅ Module RMI commun construit\"\n    else\n        echo \"⚠️  Module rmi-common non trouvé\"\n        return 1\n    fi\n    \n    echo \"\"\n    echo \"🚀 Lancement des services (dans des processes séparés)...\"\n    echo \"\"\n    \n    # Stock Service\n    echo \"📦 Démarrage Stock Service (port 8081, RMI 1099)...\"\n    cd stock-service\n    mvn clean spring-boot:run &\n    STOCK_PID=$!\n    cd ..\n    \n    sleep 5\n    \n    # Ventes Service\n    echo \"📦 Démarrage Ventes Service (port 8082, RMI 1100)...\"\n    cd ventes-service\n    mvn clean spring-boot:run &\n    VENTES_PID=$!\n    cd ..\n    \n    sleep 5\n    \n    # Finance Service\n    echo \"📦 Démarrage Finance Service (port 8083, RMI 1101)...\"\n    cd finance-service\n    mvn clean spring-boot:run &\n    FINANCE_PID=$!\n    cd ..\n    \n    sleep 5\n    \n    # API Gateway\n    echo \"📦 Démarrage API Gateway (port 8080)...\"\n    cd api-gateway\n    mvn clean spring-boot:run &\n    GATEWAY_PID=$!\n    cd ..\n    \n    echo \"\"\n    echo \"═════════════════════════════════════════════════════════════════════\"\n    echo \"✅ Services démarrés en local!\"\n    echo \"═════════════════════════════════════════════════════════════════════\"\n    echo \"\"\n    echo \"PIDs des processus:\"\n    echo \"   • Stock Service   : $STOCK_PID\"\n    echo \"   • Ventes Service  : $VENTES_PID\"\n    echo \"   • Finance Service : $FINANCE_PID\"\n    echo \"   • API Gateway     : $GATEWAY_PID\"\n    echo \"\"\n    echo \"📌 Appuyez sur Ctrl+C pour arrêter tous les services\"\n    echo \"\"\n    \n    wait\n}\n\n# Fonction pour arrêter les services\nstop_services() {\n    echo \"⏹️  Arrêt des services...\"\n    echo \"\"\n    docker-compose down\n    echo \"✅ Services arrêtés\"\n}\n\n# Fonction pour nettoyer et reconstruire\nclean_build() {\n    echo \"🧹 Nettoyage et reconstruction...\"\n    echo \"\"\n    \n    # Nettoyer RMI commun\n    if [ -d \"rmi-common\" ]; then\n        cd rmi-common\n        mvn clean\n        cd ..\n    fi\n    \n    # Nettoyer les services\n    for service in stock-service ventes-service finance-service api-gateway; do\n        if [ -d \"$service\" ]; then\n            cd \"$service\"\n            mvn clean\n            cd ..\n        fi\n    done\n    \n    echo \"✅ Nettoyage terminé\"\n    echo \"\"\n    echo \"Relancer avec: ./start-with-rmi.sh docker\"\n}\n\n# Fonction pour afficher les logs\nshow_logs() {\n    echo \"📋 Affichage des logs...\"\n    echo \"\"\n    docker-compose logs -f\n}\n\n# Traiter les arguments\nif [ $# -eq 0 ]; then\n    # Par défaut, lancer avec Docker\n    start_docker\nelif [ \"$1\" = \"docker\" ]; then\n    start_docker\nelif [ \"$1\" = \"local\" ]; then\n    start_local\nelif [ \"$1\" = \"stop\" ]; then\n    stop_services\nelif [ \"$1\" = \"clean\" ]; then\n    clean_build\nelif [ \"$1\" = \"logs\" ]; then\n    show_logs\nelse\n    echo \"❌ Option inconnue: $1\"\n    echo \"\"\n    show_help\n    exit 1\nfi\n"